export const BASE_CAPACITY = 6;

// ---- grid: areas snake through 4 columns, row after row, so each new yard touches the previous one ----
const COLS = [[-12, 12], [12, 38], [38, 64], [64, 90]];
const ROWS = [[-15, 13], [13, 41], [41, 69], [69, 97], [97, 125]];   // the fourth row is Industrial City, the fifth Commercial Metropolis
const rect = (col, row) => ({ minX: COLS[col][0], maxX: COLS[col][1], minZ: ROWS[row][0], maxZ: ROWS[row][1] });
const round2 = n => { const p = Math.pow(10, Math.max(0, Math.floor(Math.log10(n)) - 1)); return Math.round(n / p) * p; };

/**
 * Build a standard yard: optional raw source, a machine bought on the first plot, a shop,
 * then worker / speed / second machine / second worker / perk, then the gate to the next yard.
 * fetch: false = the workers here carry finished goods only. Used where every material comes from far
 * away: a worker sent across the map comes back to a machine the trucks have filled, and stands there
 * with full hands while the finished goods pile up behind them (the simulator found yards stuck that way).
 */
function makeArea({ id, name, col, row, ground, source, recipe, cost, perk, gate, shopName, location = 'town', fetch = true }) {
  const bounds = rect(col, row);
  const cx = (bounds.minX + bounds.maxX) / 2, cz = (bounds.minZ + bounds.maxZ) / 2;
  const R = RECIPES[recipe], product = R.output;
  const stations = [];
  if (source) stations.push({ id: id + ':src', type: 'source', item: R.input, x: cx - 7, z: cz - 10, pile: source.pile || 'heap', prop: source.prop || 'none', name: source.name });
  stations.push({ id: id + ':shop', type: 'shop', items: [product], x: cx, z: cz + 9, name: shopName || 'Sell' });
  const proc = n => ({ id: `${id}:proc${n}`, type: 'processor', recipe, x: cx + 4, z: n === 1 ? cz - 10 : cz - 2 });
  const perkEffect = perk?.capacity
    ? { label: 'Bigger backpack', icon: '🎒', desc: `Carry ${perk.capacity} items at once`, effect: { type: 'capacity', value: perk.capacity } }
    : { label: 'Premium ' + ITEMS[product].label, icon: '💎', desc: `${cap(ITEMS[product].label)} sell for twice the price`, effect: { type: 'price', item: product, mult: 2 } };
  const upgrades = [
    { id: id + ':proc1',   label: R.name,                 cost: round2(cost),       icon: '🏭', desc: describe(R),                     plot: [cx + 4, cz - 10], effect: { type: 'station', station: proc(1) } },
    { id: id + ':worker1', label: 'Hire worker',          cost: round2(cost * 1.5), icon: '👷', desc: 'A helper runs this yard for you',  plot: [cx - 6, cz - 3],  effect: { type: 'worker' } },
    { id: id + ':speed',   label: 'Faster ' + R.name.toLowerCase(), cost: round2(cost * 2.2), icon: '⚡', desc: 'Works twice as fast',      plot: [cx - 5, cz + 3],  effect: { type: 'speed', recipe, mult: 2 } },
    { id: id + ':proc2',   label: 'Second ' + R.name.toLowerCase(), cost: round2(cost * 3),   icon: '🏭', desc: 'One more machine',          plot: [cx + 4, cz - 2],  effect: { type: 'station', station: proc(2) } },
    { id: id + ':worker2', label: 'Second worker',        cost: round2(cost * 3.8), icon: '👷', desc: 'Another helper',                   plot: [cx - 7, cz + 10], effect: { type: 'worker' } },
    { id: id + ':perk',    ...perkEffect,                 cost: round2(cost * 5),                                                          plot: [cx + 5.5, cz + 10] },
  ];
  return {
    id, name, bounds, ground, location,
    stations,
    workerJob: { items: fetch ? [product, R.input, R.input2].filter(Boolean) : [product] },
    workerSpawn: [cx - 1, cz + 3],
    upgrades,
    gate: gate ? { cost: round2(cost * 8), next: gate.next, side: gate.side, at: gate.side === 's' || gate.side === 'n' ? cx + 9.5 : cz + 5, label: 'Expand: ' + gate.name, icon: '🏗️', desc: gate.desc || 'Open the ' + gate.name.toLowerCase() } : null,
  };
}
const cap = s => s[0].toUpperCase() + s.slice(1);
function describe(R) {
  const i = ITEMS[R.input].label, o = ITEMS[R.output].label;
  if (R.input2) return `Turns ${i} and ${ITEMS[R.input2].label} into ${o}`;
  return `Turns ${R.inCount > 1 ? R.inCount + ' ' : ''}${i} into ${R.outCount > 1 ? R.outCount + ' ' : ''}${o}`;
}

