/** The yards a worker of `areaId` delivers to: their own and the ones a gate connects it with. */
export function reachOf(areaId, areas = AREAS) {
  const out = [areaId];
  for (const a of areas) {
    if (a.id === areaId && a.gate) out.push(a.gate.next);
    if (a.gate && a.gate.next === areaId) out.push(a.id);
  }
  return out;
}

// ---- apply the tuned balance ----
for (const id in PRICES) if (ITEMS[id]) ITEMS[id].price = PRICES[id];
for (const a of AREAS) {
  for (const u of a.upgrades) if (COSTS[u.id]) u.cost = COSTS[u.id];
  if (a.gate && COSTS['gate:' + a.id]) a.gate.cost = COSTS['gate:' + a.id];
}

/** Flat list of every purchasable thing (upgrades + gates), each tagged with its area. */
export function allUpgrades(areas = AREAS) {
  const out = [];
  for (const a of areas) {
    for (const u of a.upgrades) out.push({ ...u, area: a.id });
    if (a.gate) {
      const g = a.gate;
      out.push({ id: 'gate:' + a.id, label: g.label, cost: g.cost, icon: g.icon, desc: g.desc, area: a.id,
        gate: true, effect: { type: 'area', area: g.next } });
    }
  }
  return out;
}

/** Geometry of a gate on an area's fence: centre point, outward normal, and whether it runs along x. */
export function gateGeom(bounds, gate) {
  const b = bounds, s = gate.side;
  if (s === 'e') return { x: b.maxX, z: gate.at, nx: 1, nz: 0 };
  if (s === 'w') return { x: b.minX, z: gate.at, nx: -1, nz: 0 };
  if (s === 's') return { x: gate.at, z: b.maxZ, nx: 0, nz: 1 };
  return { x: gate.at, z: b.minZ, nx: 0, nz: -1 };
}
